"use client";

import React, { useState } from "react";

import Image from "next/image";
import Link from "next/link";
import { useRouter } from "next/router";

import { cn } from "@/registry/utils/utils";

export const lightBg = "#a3c2e7";
export const baseBg = "#859cb7";
export const hoverBg = "#647991";

export default function NavbarActionButton({ header }) {
	const [isToggleOpen, setIsToggleOpen] = useState(false);
	const router = useRouter();

	return (
		<header className="fixed top-0 z-20 w-full border-b shadow-lg border-slate-200 bg-white/90 shadow-slate-700/5 after:absolute after:left-0 after:top-full after:z-10 after:block after:h-px after:w-full after:bg-slate-200 lg:border-slate-200 lg:backdrop-blur-sm lg:after:hidden">
			<div className="relative mx-auto max-w-full px-6 lg:max-w-5xl xl:max-w-7xl 2xl:max-w-[96rem]">
				<nav
					aria-label="main navigation"
					className="flex h-[5.5rem] items-stretch justify-between font-medium text-slate-700"
					role="navigation"
				>
					{/*      <!-- Brand logo --> */}
					<Link
						id="WindUI"
						aria-label="WindUI logo"
						aria-current="page"
						className="flex items-center gap-2 py-3 text-lg whitespace-nowrap focus:outline-none lg:flex-1"
						href="/"
					>
						{!!header.globalSet?.logo.length && (
							<Image
								src={header.globalSet.logo?.[0].url}
								width={260}
								height={60}
								alt="Logo"
							/>
						)}
					</Link>
					{/*      <!-- Mobile trigger --> */}
					<button
						className={`relative order-10 block h-10 w-10 self-center lg:hidden
              ${
						isToggleOpen
							? "visible opacity-100 [&_span:nth-child(1)]:w-6 [&_span:nth-child(1)]:translate-y-0 [&_span:nth-child(1)]:rotate-45 [&_span:nth-child(2)]:-rotate-45 [&_span:nth-child(3)]:w-0 "
							: ""
					}
            `}
						onClick={() => setIsToggleOpen(!isToggleOpen)}
						aria-expanded={isToggleOpen ? "true" : "false"}
						aria-label="Toggle navigation"
					>
						<div className="absolute w-6 transform -translate-x-1/2 -translate-y-1/2 left-1/2 top-1/2">
							<span
								aria-hidden="true"
								className="absolute block h-0.5 w-9/12 -translate-y-2 transform rounded-full bg-slate-900 transition-all duration-300"
							></span>
							<span
								aria-hidden="true"
								className="absolute block h-0.5 w-6 transform rounded-full bg-slate-900 transition duration-300"
							></span>
							<span
								aria-hidden="true"
								className="absolute block h-0.5 w-1/2 origin-top-left translate-y-2 transform rounded-full bg-slate-900 transition-all duration-300"
							></span>
						</div>
					</button>
					{/*      <!-- Navigation links --> */}
					<ul
						role="menubar"
						aria-label="Select page"
						className={`absolute left-0 top-0 z-[-1] h-[28.5rem] w-full justify-center overflow-hidden  overflow-y-auto overscroll-contain bg-white/90 px-8 pb-12 pt-24 font-medium transition-[opacity,visibility] duration-300 lg:visible lg:relative lg:top-0  lg:z-0 lg:flex lg:h-full lg:w-auto lg:items-stretch lg:overflow-visible lg:bg-white/0 lg:px-0 lg:py-0  lg:pt-0 lg:opacity-100 ${
							isToggleOpen
								? "visible opacity-100 backdrop-blur-sm"
								: "invisible opacity-0"
						}`}
					>
						<li role="none" className="flex items-stretch">
							<Link
								role="menuitem"
								aria-haspopup="false"
								className={cn(
									`flex items-center gap-2 py-4 transition-colors duration-300 hover:text-[#647991] focus:text-[#647991] focus:outline-none focus-visible:outline-none lg:px-8`,
									router.asPath.includes("services") &&
										`text-[#859cb7]`
								)}
								href="/about"
							>
								<span>About</span>
							</Link>
						</li>
					</ul>
					{!!header.globalSet.button?.length && (
						<div className="flex items-center px-6 ml-auto lg:ml-0 lg:p-0">
							<Link
								className={`inline-flex items-center justify-center h-10 gap-2 px-5 text-sm font-medium tracking-wide text-white transition duration-300 rounded shadow-md whitespace-nowrap bg-[#859cb7] shadow-[#b0cef0] hover:bg-[#647991] hover:shadow-sm hover:shadow-[#a3c2e7] focus:bg-[#647991] focus:shadow-sm focus:shadow-[#647991] focus-visible:outline-none`}
								href={header.globalSet.button?.[0].linkUrl}
							>
								{header.globalSet.button?.[0].linkText}
							</Link>
						</div>
					)}
				</nav>
			</div>
		</header>
	);
}

import registry from "@/registry.json";
import { clsx, type ClassValue } from "clsx";
import type { RegistryItem } from "shadcn/registry";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const components = registry.items as unknown as RegistryItem[];

export const getComponents = (selectedTags: any[] = []): RegistryItem[] => {
	return selectedTags.length
		? components.filter((component) =>
				selectedTags.every(
					(tag) => component.meta?.tags?.includes(tag) ?? false
				)
			)
		: components;
};

export const getComponentsByNames = (names: string[]): RegistryItem[] => {
	const componentsMap = new Map(components.map((comp) => [comp.name, comp]));

	return names
		.map((name) => componentsMap.get(name))
		.filter((comp): comp is RegistryItem => comp !== undefined);
};

export const getAvailableTags = (selectedTags: any[]): any[] => {
	if (!selectedTags.length) return [];

	// Get all components that have all the selected tags
	const matchingComponents = components.filter((component) =>
		selectedTags.every((tag) => component.meta?.tags?.includes(tag) ?? false)
	);

	// Get all unique tags from the matching components
	const availableTags = new Set<any>();
	matchingComponents.forEach((component) => {
		component.meta?.tags?.forEach((tag: any) => {
			if (!selectedTags.includes(tag)) {
				availableTags.add(tag);
			}
		});
	});

	return Array.from(availableTags);
};

export const convertRegistryPaths = (content: string): string => {
	return content
		.replace(/@\/registry\/default\/ui/g, "@/components/ui")
		.replace(/@\/registry\/default\/compositions/g, "@/components")
		.replace(/@\/registry\/default\/hooks/g, "@/hooks")
		.replace(/@\/registry\/default\/lib/g, "@/lib");
};
